contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public {
        address beforeOwner = c.owner();
        require(beforeOwner == address(this));

        c.transferOwnership(newOwner);

        assert(c.owner() == newOwner);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address sender, address newOwner) public {
        require(sender != address(0));
        require(newOwner != address(0));
        require(newOwner != address(this));
        require(sender != address(c));

        if (sender == address(this)) {
            c.transferOwnership(sender);
        }

        address beforeOwner = c.owner();
        require(beforeOwner != address(0));

        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address afterOwner = c.owner();
        assert((!reverted) == (beforeOwner == address(this)));
        assert(afterOwner == (beforeOwner == address(this) ? newOwner : beforeOwner));
    }

    receive() external payable {}
}

