contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public payable {
        require(caller != address(0), "zero caller");

        address ownerBefore = c.owner();

        bool reverted;
        if (caller == address(this)) {
            try c.owned() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            (bool ok, ) = address(c).call(abi.encodeWithSignature("owned()"));
            reverted = !ok;
        }

        address ownerAfter = c.owner();

        assert(reverted == (ownerBefore != address(this)) && ownerAfter == ownerBefore);
    }

    receive() external payable {}
}

